-- ============================================================
--  006: Observer Agent (Market Analyst)
--  Adds a table to store objective performance analysis and commentary 
--  generated by the external observer agent at the end of each session.
-- ============================================================

create table if not exists session_commentary (
  id uuid primary key default gen_random_uuid(),
  session_id uuid references sessions(id) on delete cascade,
  model text,
  commentary text,
  created_at timestamptz default now()
);

-- Enable RLS for public read, service role write
alter table session_commentary enable row level security;

create policy "public can read session_commentary"
  on session_commentary for select
  to public using (true);

-- The service key (worker) bypasses RLS entirely, so it can insert.
